{"command":"cat <<'EOF' > main.go
package main

import (
	"bufio"
	"bytes"
	"crypto/rand"
	"encoding/gob"
	"encoding/json"
	"fmt"
	"io"
	"io/ioutil"
	"os"
	"os/exec"
	"path/filepath"
	"sort"
	"strconv"
	"strings"
	"time"
)

// --- Models ---

type Task struct {
	UUID         string    `json:"uuid"`
	Status       string    `json:"status"`
	ID           int       `json:"id"`
	Summary      string    `json:"summary"`
	Notes        string    `json:"notes"`
	Tags         []string  `json:"tags"`
	Project      string    `json:"project"`
	Priority     string    `json:"priority"`
	DelegatedTo  string    `json:"delegatedto"`
	Subtasks     []string  `json:"subtasks"`     // Simplified
	Dependencies []string  `json:"dependencies"` // Simplified
	Created      time.Time `json:"created"`
	Resolved     time.Time `json:"resolved"`
	Due          time.Time `json:"due"`
}

type Query struct {
	Cmd           string
	IDs           []int
	Tags          []string
	AntiTags      []string
	Project       string
	AntiProjects  []string
	Due           time.Time
	DateFilter    string
	Priority      string
	Template      int
	Text          string
	IgnoreContext bool
	Note          string
}

type State struct {
	Context Query
}

// --- YAML Parser (Minimal) ---

func parseYAML(data string) map[string]interface{} {
	res := make(map[string]interface{})
	lines := strings.Split(data, "\n")
	var currentKey string
	var inList bool
	var inMultiline bool
	var multilineLines []string

	for i := 0; i < len(lines); i++ {
		line := lines[i]
		if inMultiline {
			if strings.HasPrefix(line, "  ") {
				multilineLines = append(multilineLines, strings.TrimPrefix(line, "  "))
				continue
			} else {
				res[currentKey] = strings.Join(multilineLines, "\n") + "\n"
				inMultiline = false
				multilineLines = nil
			}
		}

		if strings.TrimSpace(line) == "" {
			continue
		}

		if strings.HasPrefix(line, "- ") {
			val := strings.TrimPrefix(line, "- ")
			if list, ok := res[currentKey].([]string); ok {
				res[currentKey] = append(list, val)
			} else {
				res[currentKey] = []string{val}
			}
			continue
		}

		parts := strings.SplitN(line, ":", 2)
		if len(parts) < 2 {
			continue
		}
		key := strings.TrimSpace(parts[0])
		val := strings.TrimSpace(parts[1])

		currentKey = key
		if val == "|" {
			inMultiline = true
			continue
		}

		if val == "[]" {
			res[key] = []string{}
		} else if strings.HasPrefix(val, "\"") && strings.HasSuffix(val, "\"") {
			res[key] = val[1 : len(val)-1]
		} else {
			res[key] = val
		}
	}
	if inMultiline {
		res[currentKey] = strings.Join(multilineLines, "\n") + "\n"
	}
	return res
}

func unmarshalTask(data string) Task {
	m := parseYAML(data)
	t := Task{}
	if v, ok := m["summary"].(string); ok {
		t.Summary = v
	}
	if v, ok := m["notes"].(string); ok {
		t.Notes = v
	}
	if v, ok := m["tags"].([]string); ok {
		t.Tags = v
	}
	if v, ok := m["project"].(string); ok {
		t.Project = v
	}
	if v, ok := m["priority"].(string); ok {
		t.Priority = v
	}
	if v, ok := m["delegatedto"].(string); ok {
		t.DelegatedTo = v
	}
	if v, ok := m["subtasks"].([]string); ok {
		t.Subtasks = v
	}
	if v, ok := m["dependencies"].([]string); ok {
		t.Dependencies = v
	}
	if v, ok := m["created"].(string); ok {
		t.Created, _ = time.Parse(time.RFC3339, v)
		if t.Created.IsZero() {
			t.Created, _ = time.Parse("2006-01-02T15:04:05.999999999Z", v)
		}
	}
	if v, ok := m["resolved"].(string); ok {
		t.Resolved, _ = time.Parse(time.RFC3339, v)
		if t.Resolved.IsZero() {
			t.Resolved, _ = time.Parse("2006-01-02T15:04:05.999999999Z", v)
		}
	}
	if v, ok := m["due"].(string); ok {
		t.Due, _ = time.Parse(time.RFC3339, v)
		if t.Due.IsZero() {
			t.Due, _ = time.Parse("2006-01-02T15:04:05.999999999Z", v)
		}
	}
	return t
}

func marshalTask(t Task) string {
	var sb strings.Builder
	fmt.Fprintf(&sb, "summary: %s\n", t.Summary)
	if t.Notes == "" {
		fmt.Fprintf(&sb, "notes: \"\"\n")
	} else if strings.Contains(t.Notes, "\n") {
		fmt.Fprintf(&sb, "notes: |\n")
		lines := strings.Split(strings.TrimSuffix(t.Notes, "\n"), "\n")
		for _, line := range lines {
			fmt.Fprintf(&sb, "  %s\n", line)
		}
	} else {
		fmt.Fprintf(&sb, "notes: %s\n", t.Notes)
	}

	fmt.Fprintf(&sb, "tags:\n")
	for _, tag := range t.Tags {
		fmt.Fprintf(&sb, "- %s\n", tag)
	}
	if len(t.Tags) == 0 {
		// Wait, executable had tags: [] if empty?
		// No, looking at my cat outputs:
		// tags: []
	}
	// Let's adjust to match executable exactly
	sb.Reset()
	fmt.Fprintf(&sb, "summary: %s\n", t.Summary)
	if t.Notes == "" {
		fmt.Fprintf(&sb, "notes: \"\"\n")
	} else if strings.Contains(t.Notes, "\n") {
		fmt.Fprintf(&sb, "notes: |\n")
		lines := strings.Split(strings.TrimSuffix(t.Notes, "\n"), "\n")
		for _, line := range lines {
			fmt.Fprintf(&sb, "  %s\n", line)
		}
	} else {
		fmt.Fprintf(&sb, "notes: %s\n", t.Notes)
	}
	if len(t.Tags) == 0 {
		fmt.Fprintf(&sb, "tags: []\n")
	} else {
		fmt.Fprintf(&sb, "tags:\n")
		for _, tag := range t.Tags {
			fmt.Fprintf(&sb, "- %s\n", tag)
		}
	}
	fmt.Fprintf(&sb, "project: %s\n", t.Project)
	fmt.Fprintf(&sb, "priority: %s\n", t.Priority)
	fmt.Fprintf(&sb, "delegatedto: %s\n", t.DelegatedTo)
	fmt.Fprintf(&sb, "subtasks: []\n")
	fmt.Fprintf(&sb, "dependencies: []\n")
	fmt.Fprintf(&sb, "created: %s\n", t.Created.Format("2006-01-02T15:04:05.999999999Z"))
	fmt.Fprintf(&sb, "resolved: %s\n", t.Resolved.Format("2006-01-02T15:04:05.999999999Z"))
	fmt.Fprintf(&sb, "due: %s\n", t.Due.Format("2006-01-02T15:04:05.999999999Z"))
	return sb.String()
}

// --- UUID ---

func generateUUID() string {
	b := make([]byte, 16)
	rand.Read(b)
	b[6] = (b[6] & 0x0f) | 0x40
	b[8] = (b[8] & 0x3f) | 0x80
	return fmt.Sprintf("%x-%x-%x-%x-%x", b[0:4], b[4:6], b[6:8], b[8:10], b[10:])
}

// --- Repo & ID Management ---

func getRepoPath() string {
	repo := os.Getenv("DSTASK_GIT_REPO")
	if repo == "" {
		repo = filepath.Join(os.Getenv("HOME"), ".dstask")
	}
	return repo
}

func loadIds(repo string) map[string]int {
	f, err := os.Open(filepath.Join(repo, ".git", "dstask", "ids.bin"))
	if err != nil {
		return make(map[string]int)
	}
	defer f.Close()
	var m map[string]int
	dec := gob.NewDecoder(f)
	dec.Decode(&m)
	return m
}

func saveIds(repo string, m map[string]int) {
	os.MkdirAll(filepath.Join(repo, ".git", "dstask"), 0755)
	f, err := os.Create(filepath.Join(repo, ".git", "dstask", "ids.bin"))
	if err != nil {
		return
	}
	defer f.Close()
	enc := gob.NewEncoder(f)
	enc.Encode(m)
}

func loadState(repo string) State {
	f, err := os.Open(filepath.Join(repo, ".git", "dstask", "state.bin"))
	if err != nil {
		return State{}
	}
	defer f.Close()
	var s State
	dec := gob.NewDecoder(f)
	dec.Decode(&s)
	return s
}

func saveState(repo string, s State) {
	os.MkdirAll(filepath.Join(repo, ".git", "dstask"), 0755)
	f, err := os.Create(filepath.Join(repo, ".git", "dstask", "state.bin"))
	if err != nil {
		return
	}
	defer f.Close()
	enc := gob.NewEncoder(f)
	enc.Encode(s)
}

// --- Git ---

func runGit(repo string, args ...string) error {
	cmd := exec.Command("git", append([]string{"-C", repo}, args...)...)
	return cmd.Run()
}

func commitTask(repo string, msg string) {
	runGit(repo, "add", ".")
	runGit(repo, "commit", "-m", msg)
}

func main() {
	repo := getRepoPath()
	if _, err := os.Stat(repo); os.IsNotExist(err) {
		os.MkdirAll(repo, 0755)
		exec.Command("git", "init", repo).Run()
		fmt.Printf("Initialized empty Git repository in %s/.git/\n\n", repo)
		fmt.Println("Add a remote repository with:")
		fmt.Println("\n\tdstask git remote add origin <repo>")
	}

	// Basic command parsing
	args := os.Args[1:]
	if len(args) == 0 {
		args = []string{"next"}
	}

	// Handle completions (dummy for now)
	if args[0] == "_completions" {
		return
	}

	// ... more to come
    fmt.Println("WIP")
}
EOF
"}

