// --- YAML Parser ---

func unmarshalTask(data string) Task {
	t := Task{Priority: "P2", Tags: []string{}, Subtasks: []string{}, Dependencies: []string{}}
	lines := strings.Split(data, "\n")
	var inMultiline bool
	var multilineLines []string
	var currentKey string

	for _, line := range lines {
		if inMultiline {
			if strings.HasPrefix(line, "  ") {
				multilineLines = append(multilineLines, strings.TrimPrefix(line, "  "))
				continue
			} else {
				if currentKey == "notes" {
					t.Notes = strings.Join(multilineLines, "\n") + "\n"
				}
				inMultiline = false
			}
		}
		if strings.TrimSpace(line) == "" {
			continue
		}
		if strings.HasPrefix(line, "- ") {
			val := strings.TrimPrefix(line, "- ")
			if currentKey == "tags" {
				t.Tags = append(t.Tags, val)
			}
			continue
		}
		parts := strings.SplitN(line, ":", 2)
		if len(parts) < 2 {
			continue
		}
		key := strings.TrimSpace(parts[0])
		val := strings.TrimSpace(parts[1])
		currentKey = key
		if val == "|" {
			inMultiline = true
			multilineLines = nil
			continue
		}
		switch key {
		case "summary":
			t.Summary = val
		case "notes":
			if val != "\"\"" {
				t.Notes = val
			}
		case "project":
			t.Project = val
		case "priority":
			t.Priority = val
		case "delegatedto":
			t.DelegatedTo = val
		case "created", "resolved", "due":
			val = strings.TrimSpace(val)
			tm, _ := time.Parse("2006-01-02T15:04:05.999999999Z", val)
			if tm.IsZero() {
				tm, _ = time.Parse(time.RFC3339, val)
			}
			if tm.IsZero() {
				tm, _ = time.Parse("2006-01-02", val)
			}
			if key == "created" {
				t.Created = tm
			} else if key == "resolved" {
				t.Resolved = tm
			} else if key == "due" {
				t.Due = tm
			}
		}
	}
	return t
}

func marshalTask(t Task) string {
	var sb strings.Builder
	fmt.Fprintf(&sb, "summary: %s\n", t.Summary)
	if t.Notes == "" {
		fmt.Fprintf(&sb, "notes: \"\"\n")
	} else if strings.Contains(t.Notes, "\n") {
		fmt.Fprintf(&sb, "notes: |\n")
		lines := strings.Split(strings.TrimSuffix(t.Notes, "\n"), "\n")
		for _, line := range lines {
			fmt.Fprintf(&sb, "  %s\n", line)
		}
	} else {
		fmt.Fprintf(&sb, "notes: %s\n", t.Notes)
	}
	if len(t.Tags) == 0 {
		fmt.Fprintf(&sb, "tags: []\n")
	} else {
		fmt.Fprintf(&sb, "tags:\n")
		for _, tag := range t.Tags {
			fmt.Fprintf(&sb, "- %s\n", tag)
		}
	}
	fmt.Fprintf(&sb, "project: %s\n", t.Project)
	fmt.Fprintf(&sb, "priority: %s\n", t.Priority)
	fmt.Fprintf(&sb, "delegatedto: %s\n", t.DelegatedTo)
	fmt.Fprintf(&sb, "subtasks: []\n")
	fmt.Fprintf(&sb, "dependencies: []\n")
	fmt.Fprintf(&sb, "created: %s\n", t.Created.UTC().Format("2006-01-02T15:04:05.999999999Z"))
	fmt.Fprintf(&sb, "resolved: %s\n", t.Resolved.UTC().Format("2006-01-02T15:04:05.999999999Z"))
	fmt.Fprintf(&sb, "due: %s\n", t.Due.UTC().Format("2006-01-02T15:04:05.999999999Z"))
	return sb.String()
}

