        sort.Strings(sortedTags)
        for _, tag := range sortedTags { fmt.Println(tag) }
    case "help":
        fmt.Println("Usage: dstask [id...] <cmd> [task summary/filter]")
        // ... (truncated help)
    case "version":
        fmt.Println("Version: Unknown")
	}
}
