package main

import (
	"crypto/rand"
	"encoding/gob"
	"encoding/json"
	"fmt"
	"io/ioutil"
	"os"
	"os/exec"
	"path/filepath"
	"sort"
	"strconv"
	"strings"
	"time"
)

// --- Models ---

const (
	StatusPending   = "pending"
	StatusActive    = "active"
	StatusResolved  = "resolved"
	StatusPaused    = "paused"
	StatusTemplate  = "template"
	StatusDeferred  = "deferred"
	StatusDelegated = "delegated"
	StatusRecurring = "recurring"
)

type Task struct {
	UUID         string    `json:"uuid"`
	Status       string    `json:"status"`
	ID           int       `json:"id"`
	Summary      string    `json:"summary"`
	Notes        string    `json:"notes"`
	Tags         []string  `json:"tags"`
	Project      string    `json:"project"`
	Priority     string    `json:"priority"`
	DelegatedTo  string    `json:"delegatedto"`
	Subtasks     []string  `json:"subtasks"`
	Dependencies []string  `json:"dependencies"`
	Created      time.Time `json:"created"`
	Resolved     time.Time `json:"resolved"`
	Due          time.Time `json:"due"`
}

type Query struct {
	Cmd           string
	IDs           []int
	Tags          []string
	AntiTags      []string
	Project       string
	AntiProjects  []string
	Due           time.Time
	DateFilter    string
	Priority      string
	Template      int
	Text          string
	IgnoreContext bool
	Note          string
}

type State struct {
	Context Query
}

// --- YAML Parser ---

func unmarshalTask(data string) Task {
	t := Task{Priority: "P2", Tags: []string{}, Subtasks: []string{}, Dependencies: []string{}}
	lines := strings.Split(data, "\n")
	var inMultiline bool
	var multilineLines []string
	var currentKey string

	for _, line := range lines {
		if inMultiline {
			if strings.HasPrefix(line, "  ") {
				multilineLines = append(multilineLines, strings.TrimPrefix(line, "  "))
				continue
			} else {
				if currentKey == "notes" {
					t.Notes = strings.Join(multilineLines, "\n") + "\n"
				}
				inMultiline = false
			}
		}
		if strings.TrimSpace(line) == "" {
			continue
		}
		if strings.HasPrefix(line, "- ") {
			val := strings.TrimPrefix(line, "- ")
			if currentKey == "tags" {
				t.Tags = append(t.Tags, val)
			}
			continue
		}
		parts := strings.SplitN(line, ":", 2)
		if len(parts) < 2 {
			continue
		}
		key := strings.TrimSpace(parts[0])
		val := strings.TrimSpace(parts[1])
		currentKey = key
		if val == "|" {
			inMultiline = true
			multilineLines = nil
			continue
		}
		switch key {
		case "summary":
			t.Summary = val
		case "notes":
			if val != "\"\"" {
				t.Notes = val
			}
		case "project":
			t.Project = val
		case "priority":
			t.Priority = val
		case "delegatedto":
			t.DelegatedTo = val
		case "created", "resolved", "due":
			val = strings.TrimSpace(val)
			tm, _ := time.Parse("2006-01-02T15:04:05.999999999Z", val)
			if tm.IsZero() {
				tm, _ = time.Parse(time.RFC3339, val)
			}
			if tm.IsZero() {
				tm, _ = time.Parse("2006-01-02", val)
			}
			if key == "created" {
				t.Created = tm
			} else if key == "resolved" {
				t.Resolved = tm
			} else if key == "due" {
				t.Due = tm
			}
		}
	}
	return t
}

func marshalTask(t Task) string {
	var sb strings.Builder
	fmt.Fprintf(&sb, "summary: %s\n", t.Summary)
	if t.Notes == "" {
		fmt.Fprintf(&sb, "notes: \"\"\n")
	} else if strings.Contains(t.Notes, "\n") {
		fmt.Fprintf(&sb, "notes: |\n")
		lines := strings.Split(strings.TrimSuffix(t.Notes, "\n"), "\n")
		for _, line := range lines {
			fmt.Fprintf(&sb, "  %s\n", line)
		}
	} else {
		fmt.Fprintf(&sb, "notes: %s\n", t.Notes)
	}
	if len(t.Tags) == 0 {
		fmt.Fprintf(&sb, "tags: []\n")
	} else {
		fmt.Fprintf(&sb, "tags:\n")
		for _, tag := range t.Tags {
			fmt.Fprintf(&sb, "- %s\n", tag)
		}
	}
	fmt.Fprintf(&sb, "project: %s\n", t.Project)
	fmt.Fprintf(&sb, "priority: %s\n", t.Priority)
	fmt.Fprintf(&sb, "delegatedto: %s\n", t.DelegatedTo)
	fmt.Fprintf(&sb, "subtasks: []\n")
	fmt.Fprintf(&sb, "dependencies: []\n")
	fmt.Fprintf(&sb, "created: %s\n", t.Created.UTC().Format("2006-01-02T15:04:05.999999999Z"))
	fmt.Fprintf(&sb, "resolved: %s\n", t.Resolved.UTC().Format("2006-01-02T15:04:05.999999999Z"))
	fmt.Fprintf(&sb, "due: %s\n", t.Due.UTC().Format("2006-01-02T15:04:05.999999999Z"))
	return sb.String()
}

// --- Helpers ---

func generateUUID() string {
	b := make([]byte, 16)
	rand.Read(b)
	b[6] = (b[6] & 0x0f) | 0x40
	b[8] = (b[8] & 0x3f) | 0x80
	return fmt.Sprintf("%x-%x-%x-%x-%x", b[0:4], b[4:6], b[6:8], b[8:10], b[10:])
}

func getRepoPath() string {
	repo := os.Getenv("DSTASK_GIT_REPO")
	if repo == "" {
		repo = filepath.Join(os.Getenv("HOME"), ".dstask")
	}
	return repo
}

func loadIds(repo string) map[string]int {
	m := make(map[string]int)
	f, err := os.Open(filepath.Join(repo, ".git", "dstask", "ids.bin"))
	if err == nil {
		gob.NewDecoder(f).Decode(&m)
		f.Close()
	}
	return m
}

func saveIds(repo string, m map[string]int) {
	os.MkdirAll(filepath.Join(repo, ".git", "dstask"), 0755)
	f, err := os.Create(filepath.Join(repo, ".git", "dstask", "ids.bin"))
	if err == nil {
		gob.NewEncoder(f).Encode(m)
		f.Close()
	}
}

func loadState(repo string) State {
	var s State
	f, err := os.Open(filepath.Join(repo, ".git", "dstask", "state.bin"))
	if err == nil {
		gob.NewDecoder(f).Decode(&s)
		f.Close()
	}
	return s
}

func saveState(repo string, s State) {
	os.MkdirAll(filepath.Join(repo, ".git", "dstask"), 0755)
	f, err := os.Create(filepath.Join(repo, ".git", "dstask", "state.bin"))
	if err == nil {
		gob.NewEncoder(f).Encode(s)
		f.Close()
	}
}

func loadTasks(repo string) []Task {
	var tasks []Task
	dirs := []string{StatusPending, StatusActive, StatusResolved, StatusPaused, StatusTemplate, StatusDeferred, StatusDelegated, StatusRecurring}
	for _, dir := range dirs {
		path := filepath.Join(repo, dir)
		files, _ := ioutil.ReadDir(path)
		for _, f := range files {
			if strings.HasSuffix(f.Name(), ".yml") {
				content, _ := ioutil.ReadFile(filepath.Join(path, f.Name()))
				t := unmarshalTask(string(content))
				t.UUID = strings.TrimSuffix(f.Name(), ".yml")
				t.Status = dir
				tasks = append(tasks, t)
			}
		}
	}
	return tasks
}

func saveTask(repo string, t Task) {
	path := filepath.Join(repo, t.Status, t.UUID+".yml")
	os.MkdirAll(filepath.Dir(path), 0755)
	ioutil.WriteFile(path, []byte(marshalTask(t)), 0644)
}

func removeTaskFile(repo string, t Task) {
	dirs := []string{StatusPending, StatusActive, StatusResolved, StatusPaused, StatusTemplate, StatusDeferred, StatusDelegated, StatusRecurring}
	for _, dir := range dirs {
		os.Remove(filepath.Join(repo, dir, t.UUID+".yml"))
	}
}

func isCommand(s string) bool {
	commands := []string{"next", "add", "log", "start", "stop", "done", "modify", "edit", "context", "show-open", "show-resolved", "show-active", "show-projects", "show-tags", "show-paused", "show-templates", "show-unorganised", "open", "git", "undo", "remove", "version", "help", "bash-completion", "zsh-completion", "fish-completion", "template", "_completions"}
	for _, c := range commands {
		if s == c {
			return true
		}
	}
	return false
}

func parseArgs(args []string) Query {
	var q Query
	for _, arg := range args {
		if arg == "--" {
			q.IgnoreContext = true
			continue
		}
		if strings.HasPrefix(arg, "+") {
			q.Tags = append(q.Tags, arg[1:])
		} else if strings.HasPrefix(arg, "-") {
			q.AntiTags = append(q.AntiTags, arg[1:])
		} else if strings.HasPrefix(arg, "project:") {
			q.Project = arg[8:]
		} else if arg == "P0" || arg == "P1" || arg == "P2" || arg == "P3" {
			q.Priority = arg
		} else if strings.HasPrefix(arg, "due:") {
			q.Due, _ = time.Parse("2006-01-02", arg[4:])
		} else if id, err := strconv.Atoi(arg); err == nil && id > 0 {
			q.IDs = append(q.IDs, id)
		} else if isCommand(arg) && q.Cmd == "" {
			q.Cmd = arg
		} else {
			if q.Text == "" {
				q.Text = arg
			} else {
				q.Text += " " + arg
			}
		}
	}
	return q
}

func filterTasks(tasks []Task, q Query) []Task {
	var res []Task
	for _, t := range tasks {
		match := true
		if q.Project != "" && t.Project != q.Project {
			match = false
		}
		for _, tag := range q.Tags {
			found := false
			for _, ttag := range t.Tags {
				if ttag == tag {
					found = true
					break
				}
			}
			if !found {
				match = false
			}
		}
		for _, tag := range q.AntiTags {
			for _, ttag := range t.Tags {
				if ttag == tag {
					match = false
					break
				}
			}
		}
		if q.Priority != "" && t.Priority != q.Priority {
			match = false
		}
		if q.Text != "" && !strings.Contains(strings.ToLower(t.Summary), strings.ToLower(q.Text)) && !strings.Contains(strings.ToLower(t.Notes), strings.ToLower(q.Text)) {
			match = false
		}
		if match {
			res = append(res, t)
		}
	}
	return res
}

func isTTY() bool {
	if os.Getenv("DSTASK_FAKE_PTY") == "1" {
		return true
	}
	fi, _ := os.Stdout.Stat()
	return (fi.Mode() & os.ModeCharDevice) != 0
}

func printTable(tasks []Task) {
	if !isTTY() {
		b, _ := json.MarshalIndent(tasks, "", "  ")
		fmt.Println(string(b))
		return
	}
    // Very simple table for TUI
	fmt.Printf("\033[4m\033[38;5;250m\033[48;5;232m%-4s %-9s %-7s %-12s %-8s %s\033[0m\n", "ID", "Priority", "Tags", "Due", "Project", "Summary")
	for i, t := range tasks {
		bg := 232
		if i%2 != 0 {
			bg = 233
		}
        fg := 250
        if t.Priority == "P1" { fg = 166 }
        if t.Priority == "P0" { fg = 160 }
        if t.Status == StatusActive { 
            fg = 233
            bg = 250
        }

        tags := strings.Join(t.Tags, ",")
        due := ""
        if !t.Due.IsZero() {
            due = t.Due.Format("2 Jan 2006")
        }
		fmt.Printf("\033[38;5;%dm\033[48;5;%dm%-4d %-9s %-7s %-12s %-8s %s\033[0m\n", fg, bg, t.ID, t.Priority, tags, due, t.Project, t.Summary)
	}
    fmt.Printf("\n%d tasks.\n", len(tasks))
}

func main() {
	repo := getRepoPath()
	if _, err := os.Stat(repo); os.IsNotExist(err) {
		os.MkdirAll(repo, 0755)
		exec.Command("git", "init", repo).Run()
		fmt.Printf("Initialized empty Git repository in %s/.git/\n\n", repo)
	}

	q := parseArgs(os.Args[1:])
	state := loadState(repo)
	if !q.IgnoreContext && state.Context.Cmd != "" {
		if q.Project == "" {
			q.Project = state.Context.Project
		}
		q.Tags = append(q.Tags, state.Context.Tags...)
		q.AntiTags = append(q.AntiTags, state.Context.AntiTags...)
	}

	tasks := loadTasks(repo)
	idsMap := loadIds(repo)

	// Sort all tasks by creation date for ID assignment
	sort.Slice(tasks, func(i, j int) bool {
		return tasks[i].Created.Before(tasks[j].Created)
	})

	// Clean IDs of resolved tasks from map
	resolvedUUIDs := make(map[string]bool)
	for _, t := range tasks {
		if t.Status == StatusResolved {
			resolvedUUIDs[t.UUID] = true
			delete(idsMap, t.UUID)
		}
	}

	// Assign/Maintain IDs for open tasks
	usedIds := make(map[int]bool)
	for _, id := range idsMap {
		usedIds[id] = true
	}
	for i := range tasks {
		if tasks[i].Status != StatusResolved {
			if id, ok := idsMap[tasks[i].UUID]; ok {
				tasks[i].ID = id
			} else {
				nextId := 1
				for usedIds[nextId] {
					nextId++
				}
				tasks[i].ID = nextId
				idsMap[tasks[i].UUID] = nextId
				usedIds[nextId] = true
			}
		}
	}
	saveIds(repo, idsMap)

	if q.Cmd == "" {
		q.Cmd = "next"
	}

	switch q.Cmd {
	case "add":
		t := Task{
			UUID:    generateUUID(),
			Status:  StatusPending,
			Summary: q.Text,
			Tags:    q.Tags,
			Project: q.Project,
			Priority: q.Priority,
			Created: time.Now(),
		}
		if t.Priority == "" { t.Priority = "P2" }
		saveTask(repo, t)
        idsMap[t.UUID] = idsMap[t.UUID] // ensure it's in the map for commit msg
        id := idsMap[t.UUID]
		commitMsg := fmt.Sprintf("Added %d: %s", id, t.Summary)
		fmt.Printf("\n%s\n", commitMsg)
		exec.Command("git", "-C", repo, "add", ".").Run()
		out, _ := exec.Command("git", "-C", repo, "commit", "-m", commitMsg).CombinedOutput()
		fmt.Printf("\033[38;5;245m%s\033[0m", string(out))

	case "next", "show-open":
		var openTasks []Task
		for _, t := range tasks {
			if t.Status != StatusResolved && t.Status != StatusTemplate {
				openTasks = append(openTasks, t)
			}
		}
		filtered := filterTasks(openTasks, q)
		sort.Slice(filtered, func(i, j int) bool {
			if filtered[i].Priority != filtered[j].Priority {
				return filtered[i].Priority < filtered[j].Priority
			}
			return filtered[i].Created.Before(filtered[j].Created)
		})
		printTable(filtered)

	case "done":
		for _, id := range q.IDs {
			for i, t := range tasks {
				if t.ID == id {
					removeTaskFile(repo, t)
					tasks[i].Status = StatusResolved
					tasks[i].Resolved = time.Now()
					saveTask(repo, tasks[i])
					commitMsg := fmt.Sprintf("Resolved %d: %s", t.ID, t.Summary)
					fmt.Printf("\n%s\n", commitMsg)
					exec.Command("git", "-C", repo, "add", ".").Run()
					out, _ := exec.Command("git", "-C", repo, "commit", "-m", commitMsg).CombinedOutput()
					fmt.Printf("\033[38;5;245m%s\033[0m", string(out))
				}
			}
		}

    case "start":
		if len(q.IDs) > 0 {
			for _, id := range q.IDs {
				for i, t := range tasks {
					if t.ID == id {
						removeTaskFile(repo, t)
						tasks[i].Status = StatusActive
						saveTask(repo, tasks[i])
						commitMsg := fmt.Sprintf("Started %d: %s", t.ID, t.Summary)
						fmt.Printf("\n%s\n", commitMsg)
						exec.Command("git", "-C", repo, "add", ".").Run()
						out, _ := exec.Command("git", "-C", repo, "commit", "-m", commitMsg).CombinedOutput()
						fmt.Printf("\033[38;5;245m%s\033[0m", string(out))
					}
				}
			}
		} else if q.Text != "" {
            t := Task{
                UUID:    generateUUID(),
                Status:  StatusActive,
                Summary: q.Text,
                Tags:    q.Tags,
                Project: q.Project,
                Priority: q.Priority,
                Created: time.Now(),
            }
            if t.Priority == "" { t.Priority = "P2" }
            saveTask(repo, t)
            // Reload IDs to find the new one
            idsMap = loadIds(repo)
            // Need to manually assign if not there
            id := 1
            for usedIds[id] { id++ }
            idsMap[t.UUID] = id
            saveIds(repo, idsMap)
            commitMsg := fmt.Sprintf("Added and started %d: %s", id, t.Summary)
            fmt.Printf("\n%s\n", commitMsg)
            exec.Command("git", "-C", repo, "add", ".").Run()
            out, _ := exec.Command("git", "-C", repo, "commit", "-m", commitMsg).CombinedOutput()
            fmt.Printf("\033[38;5;245m%s\033[0m", string(out))
        }
    case "stop":
		for _, id := range q.IDs {
			for i, t := range tasks {
				if t.ID == id {
					removeTaskFile(repo, t)
					tasks[i].Status = StatusPaused
					saveTask(repo, tasks[i])
					commitMsg := fmt.Sprintf("Stopped %d: %s", t.ID, t.Summary)
					fmt.Printf("\n%s\n", commitMsg)
					exec.Command("git", "-C", repo, "add", ".").Run()
					out, _ := exec.Command("git", "-C", repo, "commit", "-m", commitMsg).CombinedOutput()
					fmt.Printf("\033[38;5;245m%s\033[0m", string(out))
				}
			}
		}
    case "context":
        if q.Text == "none" || q.Text == "" {
            state.Context = Query{}
        } else {
            state.Context = q
            state.Context.Cmd = "context"
        }
        saveState(repo, state)
    case "show-resolved":
        var resolvedTasks []Task
        for _, t := range tasks {
            if t.Status == StatusResolved {
                resolvedTasks = append(resolvedTasks, t)
            }
        }
        filtered := filterTasks(resolvedTasks, q)
        sort.Slice(filtered, func(i, j int) bool {
            return filtered[i].Resolved.Before(filtered[j].Resolved)
        })
        if isTTY() {
            // Table for resolved too? 
            printTable(filtered)
        } else {
            b, _ := json.MarshalIndent(filtered, "", "  ")
            fmt.Println(string(b))
        }
    case "show-projects":
        projects := make(map[string]*struct{
            Name string `json:"name"`
            TaskCount int `json:"taskCount"`
            ResolvedCount int `json:"resolvedCount"`
            Active bool `json:"active"`
            Created time.Time `json:"created"`
            Resolved time.Time `json:"resolved"`
            Priority string `json:"priority"`
        })
        for _, t := range tasks {
            if t.Project == "" { continue }
            p := projects[t.Project]
            if p == nil {
                p = &struct{
                    Name string `json:"name"`
                    TaskCount int `json:"taskCount"`
                    ResolvedCount int `json:"resolvedCount"`
                    Active bool `json:"active"`
                    Created time.Time `json:"created"`
                    Resolved time.Time `json:"resolved"`
                    Priority string `json:"priority"`
                }{Name: t.Project, Priority: "P2"}
                projects[t.Project] = p
            }
            if t.Status == StatusResolved {
                p.ResolvedCount++
                if t.Resolved.After(p.Resolved) { p.Resolved = t.Resolved }
            } else {
                p.TaskCount++
                if t.Status == StatusActive { p.Active = true }
                if t.Created.Before(p.Created) || p.Created.IsZero() { p.Created = t.Created }
                if t.Priority < p.Priority { p.Priority = t.Priority }
            }
        }
        var res []interface{}
        keys := make([]string, 0, len(projects))
        for k := range projects { keys = append(keys, k) }
        sort.Strings(keys)
        for _, k := range keys { res = append(res, projects[k]) }
        b, _ := json.MarshalIndent(res, "", "  ")
        fmt.Println(string(b))
    case "show-tags":
        tags := make(map[string]bool)
        filtered := filterTasks(tasks, q)
        for _, t := range filtered {
            if t.Status != StatusResolved {
                for _, tag := range t.Tags { tags[tag] = true }
            }
        }
        var sortedTags []string
        for tag := range tags { sortedTags = append(sortedTags, tag) }
        sort.Strings(sortedTags)
        for _, tag := range sortedTags { fmt.Println(tag) }
    case "help":
        fmt.Println("Usage: dstask [id...] <cmd> [task summary/filter]")
        // ... (truncated help)
    case "version":
        fmt.Println("Version: Unknown")
	}
}
EOF
./compile.sh
"}

