	IDs           []int
	Tags          []string
	AntiTags      []string
	Project       string
	AntiProjects  []string
	Due           time.Time
	Priority      string
	Text          string
	IgnoreContext bool
}

type State struct {
	Context Query
}

func unmarshalTask(data string) Task {
	t := Task{Priority: "P2", Tags: []string{}, Subtasks: []string{}, Dependencies: []string{}}
	lines := strings.Split(data, "\n")
	var inMultiline bool
	var multilineLines []string
	var currentKey string

	for _, line := range lines {
		if inMultiline {
			if strings.HasPrefix(line, "  ") {
				multilineLines = append(multilineLines, strings.TrimPrefix(line, "  "))
				continue
			} else {
				if currentKey == "notes" { t.Notes = strings.Join(multilineLines, "\n") + "\n" }
				inMultiline = false
			}
		}
		if strings.TrimSpace(line) == "" { continue }
		if strings.HasPrefix(line, "- ") {
			if currentKey == "tags" { t.Tags = append(t.Tags, strings.TrimPrefix(line, "- ")) }
			continue
		}
		parts := strings.SplitN(line, ":", 2)
		if len(parts) < 2 { continue }
		key, val := strings.TrimSpace(parts[0]), strings.TrimSpace(parts[1])
		currentKey = key
		if val == "|" { inMultiline = true; multilineLines = nil; continue }
		switch key {
		case "summary": t.Summary = val
		case "notes": if val != "\"\"" { t.Notes = val }
		case "project": t.Project = val
		case "priority": t.Priority = val
		case "created", "resolved", "due":
			tm, _ := time.Parse("2006-01-02T15:04:05.999999999Z", val)
			if tm.IsZero() { tm, _ = time.Parse(time.RFC3339, val) }
			if tm.IsZero() { tm, _ = time.Parse("2006-01-02", val) }
			if key == "created" { t.Created = tm } else if key == "resolved" { t.Resolved = tm } else if key == "due" { t.Due = tm }
		}
	}
	return t
}

func marshalTask(t Task) string {
	var sb strings.Builder
	fmt.Fprintf(&sb, "summary: %s\n", t.Summary)
	if t.Notes == "" { fmt.Fprintf(&sb, "notes: \"\"\n")
	} else if strings.Contains(t.Notes, "\n") {
		fmt.Fprintf(&sb, "notes: |\n")
		for _, line := range strings.Split(strings.TrimSuffix(t.Notes, "\n"), "\n") { fmt.Fprintf(&sb, "  %s\n", line) }
	} else { fmt.Fprintf(&sb, "notes: %s\n", t.Notes) }
	if len(t.Tags) == 0 { fmt.Fprintf(&sb, "tags: []\n")
	} else {
		fmt.Fprintf(&sb, "tags:\n")
		for _, tag := range t.Tags { fmt.Fprintf(&sb, "- %s\n", tag) }
	}
	fmt.Fprintf(&sb, "project: %s\npriority: %s\ndelegatedto: %s\nsubtasks: []\ndependencies: []\n", t.Project, t.Priority, t.DelegatedTo)
	fmt.Fprintf(&sb, "created: %s\n", t.Created.UTC().Format("2006-01-02T15:04:05.999999999Z"))
	fmt.Fprintf(&sb, "resolved: %s\n", t.Resolved.UTC().Format("2006-01-02T15:04:05.999999999Z"))
	fmt.Fprintf(&sb, "due: %s\n", t.Due.UTC().Format("2006-01-02T15:04:05.999999999Z"))
	return sb.String()
}

func generateUUID() string {
	b := make([]byte, 16)
	rand.Read(b); b[6] = (b[6] & 0x0f) | 0x40; b[8] = (b[8] & 0x3f) | 0x80
	return fmt.Sprintf("%x-%x-%x-%x-%x", b[0:4], b[4:6], b[6:8], b[8:10], b[10:])
}

func getRepoPath() string {
	repo := os.Getenv("DSTASK_GIT_REPO")
	if repo == "" { repo = filepath.Join(os.Getenv("HOME"), ".dstask") }
	return repo
}

func loadIds(repo string) map[string]int {
	m := make(map[string]int)
	f, err := os.Open(filepath.Join(repo, ".git", "dstask", "ids.bin"))
	if err == nil { gob.NewDecoder(f).Decode(&m); f.Close() }
	return m
}

func saveIds(repo string, m map[string]int) {
	os.MkdirAll(filepath.Join(repo, ".git", "dstask"), 0755)
	f, err := os.Create(filepath.Join(repo, ".git", "dstask", "ids.bin"))
	if err == nil { gob.NewEncoder(f).Encode(m); f.Close() }
}

func loadState(repo string) State {
	var s State
	f, err := os.Open(filepath.Join(repo, ".git", "dstask", "state.bin"))
	if err == nil { gob.NewDecoder(f).Decode(&s); f.Close() }
	return s
}

func saveState(repo string, s State) {
	os.MkdirAll(filepath.Join(repo, ".git", "dstask"), 0755)
	f, err := os.Create(filepath.Join(repo, ".git", "dstask", "state.bin"))
	if err == nil { gob.NewEncoder(f).Encode(s); f.Close() }
}

func loadTasks(repo string) []Task {
	var tasks []Task
	dirs := []string{StatusPending, StatusActive, StatusResolved, StatusPaused, StatusTemplate, StatusDeferred, StatusDelegated, StatusRecurring}
	for _, dir := range dirs {
		files, _ := ioutil.ReadDir(filepath.Join(repo, dir))
		for _, f := range files {
			if strings.HasSuffix(f.Name(), ".yml") {
				content, _ := ioutil.ReadFile(filepath.Join(repo, dir, f.Name()))
				t := unmarshalTask(string(content))
				t.UUID = strings.TrimSuffix(f.Name(), ".yml"); t.Status = dir
				tasks = append(tasks, t)
			}
		}
	}
	return tasks
}

func isCommand(s string) bool {
	cmds := []string{"next", "add", "log", "start", "stop", "done", "modify", "edit", "context", "show-open", "show-resolved", "show-active", "show-projects", "show-tags", "show-paused", "show-templates", "show-unorganised", "open", "git", "undo", "remove", "version", "help"}
	for _, c := range cmds { if s == c { return true } }
	return false
}

func parseArgs(args []string) Query {
	var q Query
	for _, arg := range args {
		if arg == "--" { q.IgnoreContext = true; continue }
		if strings.HasPrefix(arg, "+") { q.Tags = append(q.Tags, arg[1:])
		} else if strings.HasPrefix(arg, "-") { q.AntiTags = append(q.AntiTags, arg[1:])
		} else if strings.HasPrefix(arg, "project:") { q.Project = arg[8:]
		} else if arg == "P0" || arg == "P1" || arg == "P2" || arg == "P3" { q.Priority = arg
		} else if id, err := strconv.Atoi(arg); err == nil && id > 0 { q.IDs = append(q.IDs, id)
		} else if isCommand(arg) && q.Cmd == "" { q.Cmd = arg
		} else {
			if q.Text == "" { q.Text = arg } else { q.Text += " " + arg }
		}
	}
	return q
}

func filterTasks(tasks []Task, q Query) []Task {
	var res []Task
	for _, t := range tasks {
		match := true
		if q.Project != "" && t.Project != q.Project { match = false }
		for _, tag := range q.Tags {
			found := false
			for _, ttag := range t.Tags { if ttag == tag { found = true; break } }
			if !found { match = false }
		}
		for _, tag := range q.AntiTags {
			for _, ttag := range t.Tags { if ttag == tag { match = false; break } }
		}
		if q.Priority != "" && t.Priority != q.Priority { match = false }
		if q.Text != "" && !strings.Contains(strings.ToLower(t.Summary), strings.ToLower(q.Text)) { match = false }
		if match { res = append(res, t) }
	}
	return res
}

func printTable(tasks []Task) {
	if os.Getenv("DSTASK_FAKE_PTY") != "1" {
		fi, _ := os.Stdout.Stat()
		if (fi.Mode() & os.ModeCharDevice) == 0 {
			b, _ := json.MarshalIndent(tasks, "", "  "); fmt.Println(string(b)); return
		}
	}
	fmt.Printf("\033[4m\033[38;5;250m\033[48;5;232m%-4s %-9s %-7s %-12s %-8s %s\033[0m\n", "ID", "Priority", "Tags", "Due", "Project", "Summary")
	for i, t := range tasks {
		bg, fg := 232, 250
		if i%2 != 0 { bg = 233 }
		if t.Priority == "P1" { fg = 166 } else if t.Priority == "P0" { fg = 160 }
		if t.Status == StatusActive { fg, bg = 233, 250 }
		due := ""
		if !t.Due.IsZero() { due = t.Due.Format("2 Jan 2006") }
		fmt.Printf("\033[38;5;%dm\033[48;5;%dm%-4d %-9s %-7s %-12s %-8s %s\033[0m\n", fg, bg, t.ID, t.Priority, strings.Join(t.Tags, ","), due, t.Project, t.Summary)
	}
	fmt.Printf("\n%d tasks.\n", len(tasks))
}

func main() {
	repo := getRepoPath()
	if _, err := os.Stat(repo); os.IsNotExist(err) {
		os.MkdirAll(repo, 0755); exec.Command("git", "init", repo).Run()
		fmt.Printf("Initialized empty Git repository in %s/.git/\n\n", repo)
	}
	q := parseArgs(os.Args[1:]); state := loadState(repo)
	if !q.IgnoreContext && state.Context.Cmd != "" {
		if q.Project == "" { q.Project = state.Context.Project }
		q.Tags = append(q.Tags, state.Context.Tags...); q.AntiTags = append(q.AntiTags, state.Context.AntiTags...)
	}
	tasks := loadTasks(repo); idsMap := loadIds(repo)
	sort.Slice(tasks, func(i, j int) bool { return tasks[i].Created.Before(tasks[j].Created) })
	usedIds := make(map[int]bool)
	for _, t := range tasks { if t.Status != StatusResolved { if id, ok := idsMap[t.UUID]; ok { usedIds[id] = true } } else { delete(idsMap, t.UUID) } }
	for i := range tasks {
		if tasks[i].Status != StatusResolved {
			if id, ok := idsMap[tasks[i].UUID]; ok { tasks[i].ID = id
			} else {
				nextId := 1
				for usedIds[nextId] { nextId++ }
				tasks[i].ID = nextId; idsMap[tasks[i].UUID] = nextId; usedIds[nextId] = true
			}
		}
	}
	saveIds(repo, idsMap)
	if q.Cmd == "" { q.Cmd = "next" }
	switch q.Cmd {
	case "add":
		t := Task{UUID: generateUUID(), Status: StatusPending, Summary: q.Text, Tags: q.Tags, Project: q.Project, Priority: q.Priority, Created: time.Now()}
		if t.Priority == "" { t.Priority = "P2" }
		path := filepath.Join(repo, t.Status, t.UUID+".yml"); os.MkdirAll(filepath.Dir(path), 0755); ioutil.WriteFile(path, []byte(marshalTask(t)), 0644)
		idsMap[t.UUID] = idsMap[t.UUID] // Bug fix: this was already assigned above
		id := idsMap[t.UUID]
        saveIds(repo, idsMap) // Save again
		commitMsg := fmt.Sprintf("Added %d: %s", id, t.Summary)
		fmt.Printf("\n%s\n", commitMsg); exec.Command("git", "-C", repo, "add", ".").Run()
		out, _ := exec.Command("git", "-C", repo, "commit", "-m", commitMsg).CombinedOutput(); fmt.Printf("\033[38;5;245m%s\033[0m", string(out))
	case "next", "show-open":
		var open []Task
		for _, t := range tasks { if t.Status != StatusResolved && t.Status != StatusTemplate { open = append(open, t) } }
		filtered := filterTasks(open, q)
		sort.Slice(filtered, func(i, j int) bool {
			if filtered[i].Priority != filtered[j].Priority { return filtered[i].Priority < filtered[j].Priority }
			return filtered[i].Created.Before(filtered[j].Created)
		})
		printTable(filtered)
	case "done":
		for _, id := range q.IDs {
			for _, t := range tasks {
				if t.ID == id {
					os.Remove(filepath.Join(repo, t.Status, t.UUID+".yml")); t.Status, t.Resolved = StatusResolved, time.Now()
					path := filepath.Join(repo, t.Status, t.UUID+".yml"); os.MkdirAll(filepath.Dir(path), 0755); ioutil.WriteFile(path, []byte(marshalTask(t)), 0644)
					commitMsg := fmt.Sprintf("Resolved %d: %s", t.ID, t.Summary); fmt.Printf("\n%s\n", commitMsg)
					exec.Command("git", "-C", repo, "add", ".").Run(); out, _ := exec.Command("git", "-C", repo, "commit", "-m", commitMsg).CombinedOutput()
					fmt.Printf("\033[38;5;245m%s\033[0m", string(out))
				}
			}
		}
	case "start":
		if len(q.IDs) > 0 {
			for _, id := range q.IDs {
				for _, t := range tasks {
					if t.ID == id {
						os.Remove(filepath.Join(repo, t.Status, t.UUID+".yml")); t.Status = StatusActive
						path := filepath.Join(repo, t.Status, t.UUID+".yml"); os.MkdirAll(filepath.Dir(path), 0755); ioutil.WriteFile(path, []byte(marshalTask(t)), 0644)
						commitMsg := fmt.Sprintf("Started %d: %s", t.ID, t.Summary); fmt.Printf("\n%s\n", commitMsg)
						exec.Command("git", "-C", repo, "add", ".").Run(); out, _ := exec.Command("git", "-C", repo, "commit", "-m", commitMsg).CombinedOutput()
						fmt.Printf("\033[38;5;245m%s\033[0m", string(out))
					}
				}
			}
		}
    case "context":
        if q.Text == "none" { state.Context = Query{} } else { state.Context = q; state.Context.Cmd = "context" }
        saveState(repo, state)
	}
}
EOF
./compile.sh
"}

