func loadTasks(repo string) []Task {
	var tasks []Task
	dirs := []string{StatusPending, StatusActive, StatusResolved, StatusPaused, StatusTemplate, StatusDeferred, StatusDelegated, StatusRecurring}
	for _, dir := range dirs {
		files, _ := ioutil.ReadDir(filepath.Join(repo, dir))
