func filterTasks(tasks []Task, q Query) []Task {
	var res []Task
	for _, t := range tasks {
		match := true
		if q.Project != "" && t.Project != q.Project { match = false }
		for _, tag := range q.Tags {
			found := false
			for _, ttag := range t.Tags { if ttag == tag { found = true; break } }
			if !found { match = false }
		}
		for _, tag := range q.AntiTags {
			for _, ttag := range t.Tags { if ttag == tag { match = false; break } }
