	case "add":
		t := tasks[len(tasks)-1]; saveTask(repo, t)
		commitMsg := fmt.Sprintf("Added %d: %s", t.ID, t.Summary); fmt.Printf("\n%s\n", commitMsg)
		exec.Command("git", "-C", repo, "add", ".").Run(); out, _ := exec.Command("git", "-C", repo, "commit", "-m", commitMsg).CombinedOutput()
		fmt.Printf("\033[38;5;245m%s\033[0m", string(out))
	case "next", "show-open":
		var open []Task
		for _, t := range tasks { if t.Status != StatusResolved && t.Status != StatusTemplate { open = append(open, t) } }
		filtered := filterTasks(open, q)
		sort.Slice(filtered, func(i, j int) bool {
			if filtered[i].Priority != filtered[j].Priority { return filtered[i].Priority < filtered[j].Priority }
			return filtered[i].Created.Before(filtered[j].Created)
		})
		printTable(filtered)
	case "done":
		for _, id := range q.IDs {
			for _, t := range tasks {
				if t.ID == id {
					os.Remove(filepath.Join(repo, t.Status, t.UUID+".yml")); t.Status, t.Resolved = StatusResolved, time.Now()
					saveTask(repo, t)
					commitMsg := fmt.Sprintf("Resolved %d: %s", t.ID, t.Summary); fmt.Printf("\n%s\n", commitMsg)
					exec.Command("git", "-C", repo, "add", ".").Run(); out, _ := exec.Command("git", "-C", repo, "commit", "-m", commitMsg).CombinedOutput()
					fmt.Printf("\033[38;5;245m%s\033[0m", string(out))
				}
			}
		}
	case "start":
		if len(q.IDs) > 0 {
			for _, id := range q.IDs {
				for _, t := range tasks {
					if t.ID == id {
						os.Remove(filepath.Join(repo, t.Status, t.UUID+".yml")); t.Status = StatusActive
						saveTask(repo, t)
						commitMsg := fmt.Sprintf("Started %d: %s", t.ID, t.Summary); fmt.Printf("\n%s\n", commitMsg)
						exec.Command("git", "-C", repo, "add", ".").Run(); out, _ := exec.Command("git", "-C", repo, "commit", "-m", commitMsg).CombinedOutput()
						fmt.Printf("\033[38;5;245m%s\033[0m", string(out))
					}
				}
			}
		}
    case "context":
        if q.Text == "none" || q.Text == "" { state.Context = Query{} } else { state.Context = q; state.Context.Cmd = "context" }
        saveState(repo, state)
	}
}
