func unmarshalTask(data string) Task {
	t := Task{Priority: "P2", Tags: []string{}, Subtasks: []string{}, Dependencies: []string{}}
	lines := strings.Split(data, "\n")
	var inMultiline bool
	var multilineLines []string
	var currentKey string

	for _, line := range lines {
		if inMultiline {
			if strings.HasPrefix(line, "  ") {
				multilineLines = append(multilineLines, strings.TrimPrefix(line, "  "))
				continue
			} else {
				if currentKey == "notes" { t.Notes = strings.Join(multilineLines, "\n") + "\n" }
				inMultiline = false
			}
		}
		if strings.TrimSpace(line) == "" { continue }
		if strings.HasPrefix(line, "- ") {
			if currentKey == "tags" { t.Tags = append(t.Tags, strings.TrimPrefix(line, "- ")) }
			continue
		}
		parts := strings.SplitN(line, ":", 2)
		if len(parts) < 2 { continue }
		key, val := strings.TrimSpace(parts[0]), strings.TrimSpace(parts[1])
		currentKey = key
		if val == "|" { inMultiline = true; multilineLines = nil; continue }
		switch key {
		case "summary": t.Summary = val
		case "notes": if val != "\"\"" { t.Notes = val }
		case "project": t.Project = val
		case "priority": t.Priority = val
		case "delegatedto": t.DelegatedTo = val
