	cmds := []string{"next", "add", "log", "start", "stop", "done", "modify", "edit", "context", "show-open", "show-resolved", "show-active", "show-projects", "show-tags", "show-paused", "show-templates", "show-unorganised", "open", "git", "undo", "remove", "version", "help"}
